/*
 * Runtime support for the C code generated by tools/port/asm2c.py from the
 * game's hand-written ARM/Thumb routines (sound engine core and PCM mixer).
 *
 * GBA addresses that the assembly builds as constants (I/O registers) are
 * mapped to the host register array; every other address is a real host
 * pointer (the port is 32-bit on every target).
 */
#ifndef PORT_ASM_RT_H
#define PORT_ASM_RT_H

#include <stdint.h>

#include "gba.h"
#include "dma.h"
#include "syscalls.h"
#include "audio.h"
#include "audio_wrappers.h"
#include "data/audio.h"
#include "structs/audio.h"

static inline unsigned char *AsmRt_Map(u32 a)
{
    u32 o = a - 0x04000000u;
    if (o < 0x400u)
        return gHostIo + o;
    return (unsigned char *)(uintptr_t)a;
}

#define P(a) ((void *)AsmRt_Map(a))
#define LD8(a) (*(u8 *)AsmRt_Map(a))
#define LD16(a) (*(u16 *)AsmRt_Map(a))
#define LD32(a) (*(u32 *)AsmRt_Map(a))
#define ST8(a, x) (*(u8 *)AsmRt_Map(a) = (u8)(x))
#define ST16(a, x) (*(u16 *)AsmRt_Map(a) = (u16)(x))
#define ST32(a, x) (*(u32 *)AsmRt_Map(a) = (u32)(x))

/* Thumb register-specified shifts (amount = Rs & 0xff); *c is the carry flag. */
static inline u32 SHIFT_LSL(u32 x, u32 a, u32 *c)
{
    if (a == 0) return x;
    if (a < 32) { *c = (x >> (32 - a)) & 1; return x << a; }
    *c = (a == 32) ? (x & 1) : 0;
    return 0;
}

static inline u32 SHIFT_LSR(u32 x, u32 a, u32 *c)
{
    if (a == 0) return x;
    if (a < 32) { *c = (x >> (a - 1)) & 1; return x >> a; }
    *c = (a == 32) ? (x >> 31) : 0;
    return 0;
}

static inline u32 SHIFT_ASR(u32 x, u32 a, u32 *c)
{
    if (a == 0) return x;
    if (a < 32) { *c = ((u32)((s32)x >> (a - 1))) & 1; return (u32)((s32)x >> a); }
    *c = x >> 31;
    return (u32)((s32)x >> 31);
}

#endif /* PORT_ASM_RT_H */
